/**
 * 1분마다 이메일을 확인하여 특정 제목의 메일이 오면 스프레드시트에 내용을 기록하고
 * 내용 중 "일정명 : ????" 패턴이 있으면 캘린더에 일정을 등록하는 함수
 */
function checkEmailAndUpdateSheet() {
  // 최근 메일 중 제목이 "테스트_일정등록요청"인 메일 검색
  var threads = GmailApp.search('subject:"테스트_일정등록요청" newer_than:1m');

  // 검색된 메일이 있는 경우
  if (threads.length > 0) {
    // 가장 최근 메일 스레드 가져오기
    var latestThread = threads[0];
    var messages = latestThread.getMessages();
    var latestMessage = messages[messages.length - 1]; // 스레드의 가장 최근 메시지

    // 메일 제목과 내용 가져오기
    var mail_subject = latestMessage.getSubject();
    var mail_content = latestMessage.getPlainBody();

    // 스프레드시트 열기
    var spreadsheet = SpreadsheetApp.openById('abcd');
    var sheet = spreadsheet.getSheetByName('시트1');

    // 제목과 내용을 지정된 셀에 입력
    sheet.getRange('A1').setValue(mail_subject);
    sheet.getRange('A2').setValue(mail_content);

    // 일정명 패턴 찾기 - 더 유연한 패턴 매칭으로 개선
    var eventNameMatch = mail_content.match(/일정명\s*:\s*(.*?)(?:\r|\n|$)/);

    // 디버깅을 위해 패턴 매칭 결과 로깅
    Logger.log("메일 본문: " + mail_content);
    Logger.log("패턴 매칭 결과: " + JSON.stringify(eventNameMatch));

    // "일정명 : ????" 형태에서 ???? 부분을 정확히 추출하기 위한 추가 처리
    if (!eventNameMatch) {
      // 첫 번째 패턴이 실패한 경우 대체 패턴 시도 ("일정명 : ????" 정확히 일치)
      eventNameMatch = mail_content.match(/일정명\s*:\s*(.+?)(\r|\n|$)/);
    }

    // 일정명이 발견된 경우 캘린더에 일정 등록
    if (eventNameMatch && eventNameMatch[1]) {
      var eventName = eventNameMatch[1].trim();

      // 다음 달 1일의 날짜 계산
      var today = new Date();
      var nextMonth = new Date(today.getFullYear(), today.getMonth() + 1, 1, 9, 0, 0); // 다음 달 1일 오전 9시
      var endTime = new Date(today.getFullYear(), today.getMonth() + 1, 1, 18, 0, 0); // 다음 달 1일 오후 6시

      // Google 캘린더에 이벤트 생성
      var calendar = CalendarApp.getDefaultCalendar();
      var event = calendar.createEvent(
        eventName,
        nextMonth,
        endTime,
        {
          description: '자동 생성된 일정 - 요청 메일 제목: ' + mail_subject
        }
      );

      // 일정 생성 정보를 스프레드시트에 기록
      sheet.getRange('A3').setValue('일정 등록 완료: ' + eventName);
      sheet.getRange('A4').setValue('일정 날짜: ' + nextMonth.toLocaleDateString());
      sheet.getRange('A5').setValue('일정 시간: 09:00 ~ 18:00');
      sheet.getRange('A6').setValue('일정 ID: ' + event.getId());

      Logger.log('일정이 성공적으로 생성되었습니다: ' + eventName);
    } else {
      sheet.getRange('A3').setValue('일정 등록 요청이 발견되지 않았습니다.');
    }

    // 메일을 처리했다는 표시로 라벨 추가 또는 읽음 표시 등의 작업을 할 수 있음
    latestThread.markRead();

    // 선택적: 로그 기록
    Logger.log('새 메일이 처리됨: ' + mail_subject);
  }
}

/**
 * 트리거 설정 함수 - 이 함수는 한 번만 실행하여 트리거를 설정합니다.
 */
function createTimeDrivenTrigger() {
  // 기존 트리거 모두 삭제 (중복 방지)
  var triggers = ScriptApp.getProjectTriggers();
  for (var i = 0; i < triggers.length; i++) {
    ScriptApp.deleteTrigger(triggers[i]);
  }

  // 1분마다 실행되는 새 트리거 생성
  ScriptApp.newTrigger('checkEmailAndUpdateSheet')
    .timeBased()
    .everyMinutes(1)
    .create();

  Logger.log('1분 간격 트리거가 성공적으로 설정되었습니다.');
}
